// Normalize personnummer to 12 digits (YYYYMMDDXXXX).
const body = $json.body || $json;
const pnrRaw = body.personnummer || null;
const attempt_id = body.attempt_id || String($execution.id);
if (!pnrRaw) {
  return [{ json: { ok: false, state: 'skipped', skipEbas: true, attempt_id,
    message: 'Inget personnummer angivet' } }];
}
let pnr = String(pnrRaw).replace(/\D/g, '');
if (pnr.length < 10) {
  return [{ json: { ok: false, state: 'unavailable', error: 'invalid_input', skipEbas: true,
    attempt_id, message: 'Ogiltigt personnummer-format' } }];
}
if (pnr.length === 10) {
  const yy = parseInt(pnr.slice(0, 2), 10);
  pnr = (yy > 30 ? '19' : '20') + pnr;
}
return [{ json: { _pnr_normalized: pnr, attempt_id, skipEbas: false } }];

// Only explicit booleans are verified; errors and malformed responses preserve stored membership.
const attempt_id = $('Normalize Personnummer').first().json.attempt_id;
const memberFound = $json.response?.member_found;
if ($json.error || typeof memberFound !== 'boolean') {
  return [{ json: { ok: false, state: 'unavailable', error: 'api_unavailable', attempt_id,
    message: 'eBas kunde inte verifieras' } }];
}
return [{ json: { ok: true, state: memberFound ? 'verified_true' : 'verified_false',
  isMember: memberFound, attempt_id,
  message: memberFound ? 'Medlem i Sverok' : 'Ej medlem i Sverok' } }];

// Return a skipped/invalid-input result without any membership boolean or personnummer.
const state = $json.state === 'unavailable' ? 'unavailable' : 'skipped';
return [{ json: { ok: false, state, skipped: state === 'skipped',
  error: state === 'unavailable' ? 'invalid_input' : null,
  attempt_id: $json.attempt_id, message: $json.message } }];

